"use client"

import { Area, CartesianGrid, ComposedChart, Line, XAxis, YAxis } from "recharts"

import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"

const chartConfig = {
  range: { label: "Range", color: "var(--chart-1)" },
  value: { label: "Value", color: "var(--chart-2)" },
} satisfies ChartConfig

/**
 * Range (band) chart on the shadcn chart primitives: a Recharts range Area
 * ([low, high]) with an optional center line.
 */
function ChartRange({
  data,
  axes = true,
  legend = true,
  tooltip = true,
  className,
}: {
  data: { label: string; low: number; high: number; value?: number }[]
  axes?: boolean
  legend?: boolean
  tooltip?: boolean
  className?: string
}) {
  const rows = data.map((d) => ({ ...d, range: [d.low, d.high] as [number, number] }))
  const hasValue = data.some((d) => d.value !== undefined)
  return (
    <ChartContainer config={chartConfig} className={className}>
      <ComposedChart accessibilityLayer data={rows} margin={{ left: 12, right: 12 }}>
        {axes && <CartesianGrid vertical={false} />}
        {axes && <XAxis dataKey="label" tickLine={false} axisLine={false} tickMargin={8} />}
        {axes && <YAxis tickLine={false} axisLine={false} tickMargin={8} width={40} />}
        {tooltip && <ChartTooltip cursor={false} content={<ChartTooltipContent />} />}
        <Area dataKey="range" type="monotone" fill="var(--color-range)" fillOpacity={0.25} stroke="var(--color-range)" />
        {hasValue && <Line dataKey="value" type="monotone" stroke="var(--color-value)" strokeWidth={2} dot={false} />}
        {legend && <ChartLegend content={<ChartLegendContent />} />}
      </ComposedChart>
    </ChartContainer>
  )
}

export { ChartRange }
